"""Abstract base classes for entities, pricing, and repositories."""

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import TYPE_CHECKING, Iterator, Sequence

if TYPE_CHECKING:
    from .models import LineItem, Money


class Entity(ABC):
    """Anything with a stable identity; equality and hashing derive from it."""

    @abstractmethod
    def identity(self) -> str:
        """Return the unique key for this entity."""

    def __eq__(self, other: object) -> bool:
        """Compare identity for entities of the same concrete type."""
        if type(self) is not type(other):
            return NotImplemented
        return self.identity() == other.identity()

    def __hash__(self) -> int:
        """Hash by the concrete type name and identity."""
        return hash((type(self).__name__, self.identity()))

    def __repr__(self) -> str:
        """Return a developer-friendly representation including the identity."""
        return f"{type(self).__name__}({self.identity()!r})"


class PricingStrategy(ABC):
    """Computes an order total from line items."""

    @abstractmethod
    def price(self, items: Sequence["LineItem"]) -> "Money":
        """Return the total for the given items."""

    def __call__(self, items: Sequence["LineItem"]) -> "Money":
        """Convenience alias for :meth:`price`."""
        return self.price(items)

    @staticmethod
    def _sum_subtotals(items: Sequence["LineItem"]) -> "Money":
        """Sum the subtotal of each item, returning a zero Money for empty input."""
        from .models import Money

        if len(items) == 0:
            return Money(0)
        total = Money(0)
        for item in items:
            total = total + item.subtotal
        return total


class Repository(ABC):
    """Keyed storage of entities."""

    @abstractmethod
    def add(self, item: Entity) -> None:
        """Store an entity keyed by its identity."""

    @abstractmethod
    def get(self, key: str) -> Entity:
        """Return the entity for key; raise KeyError if missing."""

    @abstractmethod
    def remove(self, key: str) -> Entity:
        """Remove and return the entity for key; raise KeyError if missing."""

    @abstractmethod
    def __iter__(self) -> Iterator[Entity]:
        """Iterate over stored entities."""

    def __contains__(self, key: object) -> bool:
        """Return whether ``key`` is a string and its entity is present."""
        if not isinstance(key, str):
            return False

    """Remove and return the entity for key; raise KeyError if missing."""

@abstractmethod
def __iter__(self) -> Iterator[Entity]:
    """Iterate over stored entities."""

def __contains__(self, key: object) -> bool:
    """Return whether ``key`` is a string and its entity is present."""
    if not isinstance(key, str):
        return False
    try:
        self.get(key)
    except KeyError:
        return False
    return True

"""Reusable decorators for the playground package."""

from __future__ import annotations

import functools
from typing import Callable, List, Tuple, TypeVar

T = TypeVar("T")


class AuditTrail:
    """Class-based decorator recording call outcomes into an in-memory list.

    When applied it wraps a callable so that, after each invocation, an entry
    such as ``"<label>:<func_name>:ok"`` (or ``:error:<ExcName>`` on failure)
    is appended to an internal list. Entries are retrievable via
    :attr:`entries` and the trail can be reset with :meth:`clear`.
    """

    def __init__(self, label: str = "audit") -> None:
        """Initialise the trail with a non-empty string ``label``."""
        if not isinstance(label, str):
            raise TypeError("label must be str")
        if label.strip() == "":
            raise ValueError("label required")
        self._label = label
        self._entries: List[str] = []

    def __call__(self, func: Callable[..., T]) -> Callable[..., T]:
        """Decorate ``func``; returns a wrapped callable."""
        if not callable(func):
            raise TypeError("func must be callable")
        label = self._label
        entries = self._entries

        @functools.wraps(func)
        def wrapper(*args: object, **kwargs: object) -> T:
            """Invoke the wrapped function and record the outcome."""
            try:
                result = func(*args, **kwargs)
            except Exception as exc:
                entries.append(f"{label}:{func.__name__}:error:{type(exc).__name__}")
                raise
            entries.append(f"{label}:{func.__name__}:ok")
            return result

        return wrapper

    @property
    def entries(self) -> Tuple[str, ...]:
        """Immutable snapshot of recorded entries."""
        return tuple(self._entries)

    def clear(self) -> None:
        """Remove all recorded entries."""
        self._entries.clear()

    def __len__(self) -> int:
        """Return the number of recorded entries."""
        return len(self._entries)

"""Synchronous in-process event bus for the playground package."""

from __future__ import annotations

from collections.abc import Mapping
from typing import Callable, Dict, List

from .enums import EventType


class EventBus:
    """Synchronous publish/subscribe keyed by :class:`EventType`."""

    def __init__(self) -> None:
        """Initialise an empty handler registry."""
        self._handlers: Dict[EventType, List[Callable[..., None]]] = {}

    def subscribe(self, event_type: EventType, handler: Callable[..., None]) -> None:
        """Register ``handler`` to be called when ``event_type`` is published."""
        if not isinstance(event_type, EventType):
            raise TypeError("event_type must be EventType")
        if not callable(handler):
            raise TypeError("handler must be callable")
        self._handlers.setdefault(event_type, []).append(handler)

    def unsubscribe(self, event_type: EventType, handler: Callable[..., None]) -> bool:
        """Remove ``handler`` from ``event_type``; return whether it was present."""
        handlers = self._handlers.get(event_type, [])
        if handler not in handlers:
            return False
        handlers.remove(handler)
        return True

    def publish(self, event_type: EventType, payload: Mapping[str, object]) -> int:
        """Invoke every handler subscribed to ``event_type`` with ``payload``.

        Returns the number of handlers invoked.
        """
        if not isinstance(event_type, EventType):
            raise TypeError("event_type must be EventType")
        if not isinstance(payload, Mapping):
            raise TypeError("payload must be a Mapping")
        count = 0
        for handler in list(self._handlers.get(event_type, [])):
            handler(payload)
            count += 1
        return count

    def __len__(self) -> int:
        """Return the total number of registered handlers across all event types."""
        return sum(len(handlers) for handlers in self._handlers.values())

    def __contains__(self, event_type: object) -> bool:
        pass

"""Inventory ledger and warehouse location."""

from __future__ import annotations

from typing import Dict, Iterator

from .base import Entity, Repository
from .exceptions import InvalidTransitionError, OutOfStockError, UnknownSKUError
from .util import ensure_positive_int, normalize_sku


class InventoryLedger:
    """Tracks on-hand and reserved quantities per SKU."""

    def __init__(self, product_repo: Repository) -> None:
        """Create a ledger backed by ``product_repo`` for SKU validation."""
        if not isinstance(product_repo, Repository):
            raise TypeError("product_repo must be a Repository")
        self._product_repo = product_repo
        self._on_hand: Dict[str, int] = {}
        self._reserved: Dict[str, int] = {}

    def _require_sku(self, sku: str) -> str:
        """Normalise ``sku`` and raise ``UnknownSKUError`` if it is unregistered."""
        sku = normalize_sku(sku)
        if sku not in self._product_repo:
            raise UnknownSKUError(sku)
        return sku

    def add_stock(self, sku: str, quantity: int) -> int:
        """Add ``quantity`` to on-hand stock for ``sku``; return the new total."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        self._on_hand[sku] = self._on_hand.get(sku, 0) + quantity
        return self._on_hand[sku]

    def available(self, sku: str) -> int:
        """Return on-hand minus reserved for ``sku``."""
        sku = self._require_sku(sku)
        return self._on_hand.get(sku, 0) - self._reserved.get(sku, 0)

    def reserve(self, sku: str, quantity: int) -> ReservationContext:
        """Reserve ``quantity`` of ``sku`` and return a context that can commit or release it."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        avail = self.available(sku)
        if quantity > avail:
            raise OutOfStockError(sku, quantity, avail)
        self._reserved[sku] = self._reserved.get(sku, 0) + quantity
        return ReservationContext(self, sku, quantity)

    def release(self, sku: str, quantity: int) -> None:
        """Release ``quantity`` previously reserved for ``sku``."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        reserved = self._reserved.get(sku, 0)
        if quantity > reserved:
            raise InvalidTransitionError(reserved, quantity)
        self._reserved[sku] = reserved - quantity

    def commit(self, sku: str, quantity: int) -> None:
        """Commit ``quantity`` of ``sku``: decrement both reserved and on-hand."""
        quantity = ensure_positive_int(quantity, "quantity")
        sku = self._require_sku(sku)
        reserved = self._reserved.get(sku, 0)
        if quantity > reserved:
            raise InvalidTransitionError(reserved, quantity)
        self._reserved[sku] = reserved - quantity
        self._on_hand[sku] = self._on_hand.get(sku, 0) - quantity

    def __contains__(self, sku: object) -> bool:
        pass

    def __len__(self) -> int:
        """Return the number of SKUs with positive on-hand stock."""
        return sum(1 for qty in self._on_hand.values() if qty > 0)

    def __iter__(self) -> Iterator[str]:
        """Iterate over SKUs with positive on-hand stock, in sorted order."""
        for sku in sorted(k for k, v in self._on_hand.items() if v > 0):

    def __contains__(self, sku: object) -> bool:
        pass

    def __len__(self) -> int:
        """Return the number of SKUs with positive on-hand stock."""
        return sum(1 for qty in self._on_hand.values() if qty > 0)

    def __iter__(self) -> Iterator[str]:
        """Iterate over SKUs with positive on-hand stock, in sorted order."""
        for sku in sorted(k for k, v in self._on_hand.items() if v > 0):
            yield sku


class ReservationContext:
    """Context manager for a reservation; releases on exit unless committed."""

    def __init__(self, ledger: InventoryLedger, sku: str, quantity: int) -> None:
        """Create a held reservation for ``quantity`` of ``sku`` in ``ledger``."""
        self._ledger = ledger
        self._sku = sku
        self._quantity = quantity
        self._state = "held"

    @property
    def state(self) -> str:
        """Return the current reservation state."""
        return self._state

    def __enter__(self) -> ReservationContext:
        """Enter the context; raises if the reservation is not in the held state."""
        if self._state != "held":
            raise InvalidTransitionError(self._state, "held")
        return self

    def __exit__(self, exc_type: object, exc: object, tb: object) -> bool:
        """Release the reservation on exit unless it was committed."""
        if self._state == "held":
            self._ledger.release(self._sku, self._quantity)
            self._state = "released"
        return False

    def commit(self) -> None:
        """Commit the reservation, decrementing stock; raises if not held."""
        if self._state != "held":
            raise InvalidTransitionError(self._state, "committed")
        self._ledger.commit(self._sku, self._quantity)
        self._state = "committed"

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"ReservationContext({self._sku!r}, {self._quantity}, {self._state!r})"


class Warehouse(Entity):
