    def from_dict(cls, data: Mapping[str, object]) -> Product:
        """Build a product from a mapping with keys sku, name, category, unit_price_cents."""
        for key in ("sku", "name", "category", "unit_price_cents"):
            if key not in data:
                raise KeyError(key)
