class LineItem:
    """One SKU with quantity and unit price."""

    def __init__(self, sku: str, quantity: int, unit_price: Money) -> None:
        """Create a line item after validating its SKU, quantity, and price."""
        sku = normalize_sku(sku)
        quantity = ensure_positive_int(quantity, "quantity")
        if not isinstance(unit_price, Money):
            raise TypeError("unit_price must be Money")
        self._sku = sku
        self._quantity = quantity
        self._unit_price = unit_price

    @property
    def sku(self) -> str:
        """Return the line item SKU."""
        return self._sku

    @property
    def quantity(self) -> int:
        """Return the line item quantity."""
        return self._quantity

    @property
    def unit_price(self) -> Money:
        """Return the unit price."""
        return self._unit_price

    @property
    def subtotal(self) -> Money:
        """Return the line item subtotal (unit price times quantity)."""
        return self._unit_price * self._quantity

    def with_quantity(self, quantity: int) -> LineItem:
        """Return a copy of this line item with a new quantity."""
        return LineItem(self._sku, quantity, self._unit_price)

    def __eq__(self, other: object) -> bool:
        """Compare SKU, quantity, and unit price for equality."""
        if not isinstance(other, LineItem):
            return NotImplemented
        return (self._sku, self._quantity, self._unit_price) == (
            other._sku,
            other._quantity,
            other._unit_price,
        )

    def __hash__(self) -> int:
        """Hash by SKU and quantity."""
        return hash((self._sku, self._quantity))

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"LineItem({self._sku!r}, {self._quantity}, {self._unit_price!r})"

    def __hash__(self) -> int:
        """Hash by SKU and quantity."""
        return hash((self._sku, self._quantity))

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"LineItem({self._sku!r}, {self._quantity}, {self._unit_price!r})"


class Customer(Entity):
    """Buyer with a credit limit. Balance is the amount owed."""

    def __init__(self, customer_id: str, name: str, credit_limit: Money = Money(0)) -> None:
        """Create a customer with the given identity, name, and credit limit."""
        if not isinstance(customer_id, str) or customer_id.strip() == "":
            raise ValueError("customer_id required")
        if not isinstance(name, str) or name.strip() == "":
            raise ValueError("name required")
        if not isinstance(credit_limit, Money):
            raise TypeError("credit_limit must be Money")
        self._customer_id = customer_id
        self._name = name
        self._credit_limit = credit_limit
        self._balance = Money(0)

    @property
    def customer_id(self) -> str:
        """Return the customer identity."""
        return self._customer_id

    @property
    def name(self) -> str:
        """Return the customer name."""
        return self._name

    @property
    def credit_limit(self) -> Money:
        """Return the credit limit."""
        return self._credit_limit

    @property
    def balance(self) -> Money:
        """Return the current outstanding balance."""
        return self._balance

    def identity(self) -> str:
        """Return the customer_id as the entity identity."""
        return self._customer_id

    def can_afford(self, total: Money) -> bool:
        pass

    def charge(self, total: Money) -> None:
        """Increase the balance by ``total``, raising if the limit would be exceeded."""
        if not self.can_afford(total):
            raise ValueError("credit limit exceeded")
        self._balance = self._balance + total

"""Order state-machine, order aggregates, builder, and log."""

from __future__ import annotations

from typing import Dict, FrozenSet, Iterator, List, Tuple

from .base import PricingStrategy
from .enums import OrderStatus
from .exceptions import DuplicateEntityError, InvalidTransitionError
from .models import Customer, LineItem, Money
from .pricing import FlatPricing


class OrderStateMachine:
    """Legal OrderStatus transitions, data-driven via TRANSITIONS."""

    TRANSITIONS: Dict[OrderStatus, FrozenSet[OrderStatus]] = {
        OrderStatus.NEW: frozenset({OrderStatus.RESERVED, OrderStatus.CANCELLED}),
        OrderStatus.RESERVED: frozenset({OrderStatus.SHIPPED, OrderStatus.CANCELLED}),
        OrderStatus.SHIPPED: frozenset(),
        OrderStatus.CANCELLED: frozenset(),
    }

    @staticmethod
    def allowed_from(status: OrderStatus) -> FrozenSet[OrderStatus]:
        """Return the set of statuses reachable from ``status``."""
        if not isinstance(status, OrderStatus):
            raise TypeError("status must be OrderStatus")
        return OrderStateMachine.TRANSITIONS[status]

    def can_transition(self, source: OrderStatus, target: OrderStatus) -> bool:
        """Return whether ``target`` is reachable from ``source``."""
        return target in OrderStateMachine.allowed_from(source)

    def transition(self, source: OrderStatus, target: OrderStatus) -> OrderStatus:
        pass

    def __call__(self, source: OrderStatus, target: OrderStatus) -> OrderStatus:
        """Convenience alias for :meth:`transition`."""
        return self.transition(source, target)


class Order:
    """Customer order with items, status, and pricing."""

    def __init__(self, order_id: str, customer: Customer, pricing: PricingStrategy) -> None:
        """Create a new order in the NEW status for ``customer``."""
        if not isinstance(order_id, str) or order_id.strip() == "":
            raise ValueError("order_id required")
        if not isinstance(customer, Customer):
            raise TypeError("customer must be Customer")
        if not isinstance(pricing, PricingStrategy):
            raise TypeError("pricing must be PricingStrategy")
        self._order_id = order_id
        self._customer = customer
        self._pricing = pricing
        self._items: List[LineItem] = []
        self._status: OrderStatus = OrderStatus.NEW
        self._machine = OrderStateMachine()

    @property
    def order_id(self) -> str:
        """Return the order identity."""
        return self._order_id

    @property
    def customer(self) -> Customer:
        """Return the owning customer."""
        return self._customer

    @property
    def status(self) -> OrderStatus:
        """Return the current order status."""
        return self._status

    @property
    def items(self) -> Tuple[LineItem, ...]:
        """Return a tuple copy of the order's line items."""
        return tuple(self._items)

    @property
    def status(self) -> OrderStatus:
        """Return the current order status."""
        return self._status

    @property
    def items(self) -> Tuple[LineItem, ...]:
        """Return a tuple copy of the order's line items."""
        return tuple(self._items)

    @property
    def total(self) -> Money:
        """Return the total price of all line items under this order's pricing."""
        return self._pricing.price(self._items)

    def add_item(self, item: LineItem) -> None:
        """Append ``item``, merging with an existing line for the same SKU."""
        if not isinstance(item, LineItem):
            raise TypeError("item must be LineItem")
        if self._status is not OrderStatus.NEW:
            raise InvalidTransitionError(self._status, OrderStatus.NEW)
        for index, existing in enumerate(self._items):
            if existing.sku == item.sku:
                self._items[index] = existing.with_quantity(existing.quantity + item.quantity)
                return
        self._items.append(item)

    def advance(self, target: OrderStatus) -> None:
        """Transition the order to ``target`` status, raising if not allowed."""
        new_status = self._machine.transition(self._status, target)
        self._status = new_status

    def __len__(self) -> int:
        pass

    def __iter__(self) -> Iterator[LineItem]:
        """Iterate over a tuple snapshot of the order's line items."""
        return iter(tuple(self._items))

    def __eq__(self, other: object) -> bool:
        """Compare orders by identity."""
        if not isinstance(other, Order):
            return NotImplemented
        return self._order_id == other._order_id

    def __hash__(self) -> int:
        """Hash by type name and order id."""
        return hash(("Order", self._order_id))

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"Order({self._order_id!r}, {self._status.value})"


class OrderBuilder:
    """Fluent construction of an :class:`Order`."""

    def __init__(self, customer: Customer, pricing: PricingStrategy) -> None:
        """Create a builder for ``customer`` and ``pricing``."""
        if not isinstance(customer, Customer):
            raise TypeError("customer must be Customer")
        if not isinstance(pricing, PricingStrategy):
            raise TypeError("pricing must be PricingStrategy")
        self._customer = customer
        self._pricing = pricing
        self._lines: List[Tuple[str, int, Money]] = []

    @classmethod
    def for_customer(cls, customer: Customer) -> OrderBuilder:
        """Create a builder with default :class:`FlatPricing` for ``customer``."""
        return cls(customer, FlatPricing())

    def add(self, sku: str, quantity: int, unit_price: Money) -> OrderBuilder:
        """Record a line item and return self for chaining."""
        item = LineItem(sku, quantity, unit_price)
        self._lines.append((item.sku, item.quantity, item.unit_price))
        return self

    def build(self, order_id: str) -> Order:
        """Construct and return the order; raises if no lines were recorded."""

        return cls(customer, FlatPricing())

    def add(self, sku: str, quantity: int, unit_price: Money) -> OrderBuilder:
        """Record a line item and return self for chaining."""
        item = LineItem(sku, quantity, unit_price)
        self._lines.append((item.sku, item.quantity, item.unit_price))
        return self

    def build(self, order_id: str) -> Order:
        """Construct and return the order; raises if no lines were recorded."""
        if len(self._lines) == 0:
            raise ValueError("no items")
        order = Order(order_id, self._customer, self._pricing)
        for sku, quantity, unit_price in self._lines:
            order.add_item(LineItem(sku, quantity, unit_price))
        return order

    def __len__(self) -> int:
        """Return the number of recorded lines."""
        return len(self._lines)

    def __bool__(self) -> bool:
        """Return True when at least one line has been recorded."""
        return len(self) > 0


class OrderLog:
    """Ordered, deduplicated record of orders; iterable."""

    def __init__(self) -> None:
        """Create an empty order log."""
        self._orders: List[Order] = []

    def record(self, order: Order) -> None:
        """Append ``order``; raises if an order with the same id is already logged."""
        if not isinstance(order, Order):
            raise TypeError("order must be Order")
        for existing in self._orders:
            if existing.order_id == order.order_id:
                raise DuplicateEntityError(order.order_id)
        self._orders.append(order)

    def by_status(self, status: OrderStatus) -> Iterator[Order]:
        pass

    def __getitem__(self, index: int) -> Order:
        """Return the order at ``index``."""
        return self._orders[index]

    def __len__(self) -> int:
        """Return the number of logged orders."""
        return len(self._orders)

    def __iter__(self) -> Iterator[Order]:
        """Iterate over the logged orders."""
        yield from list(self._orders)

"""Pricing strategies for computing order totals."""

from __future__ import annotations

from typing import Sequence

from .base import PricingStrategy
from .models import LineItem, Money
from .util import ensure_positive_int


class FlatPricing(PricingStrategy):
    """Sum of subtotals plus flat tax in basis points."""

    def __init__(self, tax_bps: int = 0) -> None:
        """Create a pricing strategy with a tax rate in ``tax_bps`` basis points."""
        if isinstance(tax_bps, bool) or not isinstance(tax_bps, int):
            raise TypeError("tax_bps must be int")
        if tax_bps < 0 or tax_bps > 10000:
            raise ValueError("tax_bps must be 0..10000")
        self._tax_bps = tax_bps

    @property
    def tax_bps(self) -> int:
        """Return the tax rate in basis points."""
        return self._tax_bps

    def price(self, items: Sequence[LineItem]) -> Money:
        """Return the subtotal plus the configured flat tax."""
        subtotal = self._sum_subtotals(items)
        if self._tax_bps == 0:
            return subtotal
        tax = Money(subtotal.cents * self._tax_bps // 10000)
        return subtotal + tax


class BulkDiscountPricing(PricingStrategy):
    """Wraps another strategy; applies a percent discount when total quantity meets a threshold."""

    def __init__(self, base: PricingStrategy, threshold: int, percent_off: int) -> None:
        """Create a strategy that discounts ``base`` totals above ``threshold`` quantity."""
        if not isinstance(base, PricingStrategy):
            raise TypeError("base must be PricingStrategy")
        threshold = ensure_positive_int(threshold, "threshold")
        if isinstance(percent_off, bool) or not isinstance(percent_off, int):
            raise TypeError("percent_off must be int")
        if percent_off < 0 or percent_off > 100:
            raise ValueError("percent_off must be 0..100")
        self._base = base
        self._threshold = threshold
        self._percent_off = percent_off

    @property
    def threshold(self) -> int:
        """Return the qualifying total quantity."""
        return self._threshold

    @property
    def percent_off(self) -> int:
        """Return the discount percentage."""
        return self._percent_off

    def price(self, items: Sequence[LineItem]) -> Money:
        pass

    def __repr__(self) -> str:
        """Return a developer-friendly representation."""
        return f"BulkDiscountPricing(threshold={self._threshold}, percent_off={self._percent_off})"

"""In-memory repository implementation."""

from __future__ import annotations

from typing import Dict, Iterator

from .base import Entity, Repository
from .exceptions import DuplicateEntityError


class InMemoryRepository(Repository):
    """Dict-backed repository keyed by ``item.identity()``."""

    def __init__(self, entity_type: type) -> None:
        """Create a repository restricted to instances of ``entity_type``."""
        if not isinstance(entity_type, type):
            raise TypeError("entity_type must be a type")
        self._entity_type = entity_type
        self._store: Dict[str, Entity] = {}

    def add(self, item: Entity) -> None:
        """Store ``item`` keyed by its identity; raises on duplicate or wrong type."""
        if not isinstance(item, self._entity_type):
            raise TypeError(f"item must be {self._entity_type.__name__}")
        key = item.identity()
        if key in self._store:
            raise DuplicateEntityError(key)
        self._store[key] = item

    def get(self, key: str) -> Entity:
        """Return the stored entity for ``key``; raises TypeError or KeyError."""
        if not isinstance(key, str):
            raise TypeError("key must be str")
        return self._store[key]

    def remove(self, key: str) -> Entity:
        """Remove and return the entity for ``key``; raises KeyError if missing."""
        if key not in self._store:
            raise KeyError(key)
        return self._store.pop(key)

    def __contains__(self, key: object) -> bool:
        """Return whether ``key`` is a string present in the store."""
        return isinstance(key, str) and key in self._store

    def __len__(self) -> int:
        """Return the number of stored entities."""
        return len(self._store)

    def __iter__(self) -> Iterator[Entity]:
        """Iterate over stored entities in sorted key order."""
        for key in sorted(self._store):
            yield self._store[key]

